import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.LongAdder;

public class Main {
    private static int unsafeCount = 0;
    private static final AtomicInteger safeCount = new AtomicInteger();
    private static final LongAdder adderCount = new LongAdder();

    private static int payload = 0;
    private static volatile boolean ready = false;

    public static void main(String[] args) throws Exception {
        // --- 1. 原子性：丢更新复现与修复 ---
        int threads = 4;
        int rounds = 100_000;
        Thread[] workers = new Thread[threads];
        for (int i = 0; i < threads; i++) {
            workers[i] = new Thread(() -> {
                for (int j = 0; j < rounds; j++) {
                    unsafeCount++;           // 非原子，会丢更新
                    safeCount.incrementAndGet(); // CAS 保证原子
                    adderCount.increment();       // 分段累加
                }
            }, "worker-" + i);
            workers[i].start();
        }
        for (Thread w : workers) w.join();

        int expected = threads * rounds;
        System.out.println("unsafeCount = " + unsafeCount + " / expected " + expected);
        System.out.println("safeCount   = " + safeCount.get() + " / expected " + expected);
        System.out.println("adderCount  = " + adderCount.sum() + " / expected " + expected);
        assert safeCount.get() == expected;
        assert adderCount.sum() == expected;

        // --- 2. 可见性+有序性：volatile 状态发布 ---
        Thread reader = new Thread(() -> {
            while (!ready) {
                Thread.onSpinWait(); // Java 9+ 提示 CPU 减少流水线冲刷
            }
            // ready 是 volatile，happens-before 保证能看到之前写入的 payload
            System.out.println("payload via volatile flag = " + payload);
            assert payload == 42;
        }, "reader");
        reader.start();
        payload = 42;   // 普通写
        ready = true;   // volatile 写，建立 happens-before
        reader.join();
    }
}
